package com.tuap.backend.servicios;
import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
import java.lang.reflect.Field; import java.time.*; import java.util.*; import org.junit.jupiter.api.*;
import com.tuap.backend.auth.*; import com.tuap.backend.config.CleanupProperties; import com.tuap.backend.dominio.entidades.*; import com.tuap.backend.persistencia.*;
class CleanupServiceTest {
 private final Instant now=Instant.parse("2026-01-20T00:00:00Z"); private RefreshTokenDAO refresh=mock(RefreshTokenDAO.class); private PasswordResetTokenDAO resets=mock(PasswordResetTokenDAO.class); private UploadedFileDAO uploads=mock(UploadedFileDAO.class); private MensajeDAO messages=mock(MensajeDAO.class); private ClienteDAO clients=mock(ClienteDAO.class); private EntrenadorDAO trainers=mock(EntrenadorDAO.class); private FileStorageService storage=mock(FileStorageService.class); private CleanupProperties props=new CleanupProperties(); private CleanupService service;
 @BeforeEach void setup(){props.setRefreshRetentionDays(30);props.setPasswordResetRetentionDays(7);props.setOrphanUploadGraceHours(24);service=new CleanupService(refresh,resets,uploads,messages,clients,trainers,storage,props,Clock.fixed(now,ZoneOffset.UTC));when(clients.findAll()).thenReturn(List.of());when(trainers.findAll()).thenReturn(List.of());}
 @Test void refreshOnlyDeletesOldUnusable(){RefreshToken active=new RefreshToken(UUID.randomUUID(),Role.CLIENTE,"a",UUID.randomUUID(),ClientType.WEB,now.minusSeconds(10),now.plus(Duration.ofDays(1)));RefreshToken expired=new RefreshToken(UUID.randomUUID(),Role.CLIENTE,"b",UUID.randomUUID(),ClientType.WEB,now.minus(Duration.ofDays(40)),now.minus(Duration.ofDays(31)));RefreshToken revoked=new RefreshToken(UUID.randomUUID(),Role.CLIENTE,"c",UUID.randomUUID(),ClientType.WEB,now.minus(Duration.ofDays(40)),now.plus(Duration.ofDays(1)));revoked.revoke(now.minus(Duration.ofDays(31)));when(refresh.findAll()).thenReturn(List.of(active,expired,revoked));assertEquals(2,service.cleanupRefreshTokens());verify(refresh).deleteAll(List.of(expired,revoked));}
 @Test void resetOnlyDeletesOldInvalid(){PasswordResetToken valid=new PasswordResetToken(UUID.randomUUID(),Role.CLIENTE,"a",now.plus(Duration.ofHours(1)),now);PasswordResetToken expired=new PasswordResetToken(UUID.randomUUID(),Role.CLIENTE,"b",now.minus(Duration.ofDays(8)),now.minus(Duration.ofDays(9)));PasswordResetToken used=new PasswordResetToken(UUID.randomUUID(),Role.CLIENTE,"c",now.plus(Duration.ofHours(1)),now.minus(Duration.ofDays(9)));used.consume(now.minus(Duration.ofDays(8)));when(resets.findAll()).thenReturn(List.of(valid,expired,used));assertEquals(2,service.cleanupPasswordResetTokens());verify(resets).deleteAll(List.of(expired,used));}
 @Test void profileAndChatKeepReferencedAndRecentButDeleteOldOrphans(){UploadedFile assigned=file(UploadPurpose.PROFILE_IMAGE,now.minus(Duration.ofDays(2)));UploadedFile old=file(UploadPurpose.PROFILE_IMAGE,now.minus(Duration.ofDays(2)));UploadedFile recent=file(UploadPurpose.PROFILE_IMAGE,now.minus(Duration.ofHours(2)));com.tuap.backend.dominio.entidades.Cliente c=new com.tuap.backend.dominio.entidades.Cliente();c.setFotoPerfil("/api/upload/files/"+assigned.getId());when(clients.findAll()).thenReturn(List.of(c));when(uploads.findAll()).thenReturn(List.of(assigned,old,recent));assertEquals(1,service.cleanupOrphanProfileImages());verify(storage).delete(old.getStorageKey());verify(uploads).delete(old);UploadedFile linked=file(UploadPurpose.CHAT_ATTACHMENT,now.minus(Duration.ofDays(2)));UploadedFile chatOld=file(UploadPurpose.CHAT_ATTACHMENT,now.minus(Duration.ofDays(2)));when(uploads.findAll()).thenReturn(List.of(linked,chatOld));when(messages.existsByAttachmentId(linked.getId())).thenReturn(true);assertEquals(1,service.cleanupOrphanChatAttachments());verify(uploads).delete(chatOld);}
 @Test void filesystemFailureRetainsMetadataAndContinues(){UploadedFile broken=file(UploadPurpose.PROFILE_IMAGE,now.minus(Duration.ofDays(2)));UploadedFile good=file(UploadPurpose.PROFILE_IMAGE,now.minus(Duration.ofDays(2)));when(uploads.findAll()).thenReturn(List.of(broken,good));doThrow(new RuntimeException()).when(storage).delete(broken.getStorageKey());assertEquals(1,service.cleanupOrphanProfileImages());verify(uploads,never()).delete(broken);verify(uploads).delete(good);}
 private UploadedFile file(UploadPurpose purpose,Instant created){UploadedFile f=new UploadedFile(UUID.randomUUID(),Role.CLIENTE,purpose,UploadVisibility.PRIVATE,UUID.randomUUID()+".png","x.png","image/png",1);set(f,"id",UUID.randomUUID());set(f,"createdAt",created);return f;} private void set(Object o,String field,Object v){try{Field f=o.getClass().getDeclaredField(field);f.setAccessible(true);f.set(o,v);}catch(Exception e){throw new RuntimeException(e);}}
}
